-- Dev seed data. Run after 1.ddl.sql and 2.ddl.sql:
--   psql $DATABASE_URL -f db/3.dml.sql
-- All UUIDs (narratives, simulations, events, actions) are generated by the DB, and rows
-- reference each other through subqueries/joins (narrative by title, event by narrative +
-- kind + status, action by title). The narrative insert skips titles that already exist;
-- the event/action/log DO block only runs on an empty event table.

SET search_path = fresnel, public;

BEGIN;

------------------------------------------------------------------------------
-- action_type (also seeded by the DDL; kept here so the seed stands alone)
------------------------------------------------------------------------------
INSERT INTO action_type (code, label_he, active) VALUES
  ('official_response', 'הודעת דו"צ',          true),
  ('consultation',      'התייעצות',            true),
  ('reporter_contact',  'תיאום עם כתב',        true),
  ('external_contact',  'פנייה לגורם חיצוני',  true),
  ('field_collection',  'איסוף מידע מהשטח',    true),
  ('source_analysis',   'ניתוח מקורות',        true),
  ('fact_check',        'בדיקת אמינות מידע',   true),
  ('monitor',           'מעקב אחר התפתחות',    true),
  ('other',             'אחר',                 true)
ON CONFLICT (code) DO NOTHING;

------------------------------------------------------------------------------
-- narrative (arena values follow the Arena enum: israel / arab / intl)
-- narrative_id is generated; received_at is shortly after detected_at.
------------------------------------------------------------------------------
INSERT INTO narrative
  (narrative_id, title, summary, is_anomaly, arena, detected_at,
   item_list, platforms, shares_count, views_count, languages, is_flagged, received_at)
SELECT gen_random_uuid(), v.title, v.summary, v.is_anomaly, v.arena, v.detected_at,
       v.item_list, v.platforms, v.shares_count, v.views_count, v.languages, v.is_flagged,
       v.detected_at + interval '5 minutes'
FROM (VALUES
  ('תמונות מזויפות מהגבול הצפוני',
   'תמונות ישנות מופצות כאילו צולמו הלילה בגבול הצפון',
   true, ARRAY['israel'], now() - interval '3 days',
   ARRAY['item-1001','item-1002','item-1003'], ARRAY['telegram','x'],
   5400, 182000, ARRAY['he','ar'], true),
  ('שמועה על מחסור בדלק',
   'הודעות ברשתות על סגירת תחנות דלק ברחבי הארץ',
   true, ARRAY['israel'], now() - interval '2 days',
   ARRAY['item-2001','item-2002'], ARRAY['facebook','whatsapp'],
   12800, 95000, ARRAY['he'], false),
  ('קמפיין בערבית נגד הסכמי נורמליזציה',
   'רשת חשבונות מתואמת מפיצה מסרים אחידים',
   true, ARRAY['arab'], now() - interval '36 hours',
   ARRAY['item-3001','item-3002','item-3003','item-3004'], ARRAY['x','telegram','tiktok'],
   30200, 740000, ARRAY['ar'], true),
  ('סרטון מניפולטיבי על פעילות צה"ל בעזה',
   'סרטון ערוך מופץ באנגלית עם כיתוב מטעה',
   true, ARRAY['intl','arab'], now() - interval '1 day',
   ARRAY['item-4001','item-4002'], ARRAY['x','youtube','instagram'],
   8700, 410000, ARRAY['en','ar'], false),
  ('ויכוח ברשת על חוק הגיוס',
   'שיח ציבורי רגיל, ללא סימני פעילות מתואמת',
   false, ARRAY['israel'], now() - interval '12 hours',
   ARRAY['item-5001'], ARRAY['facebook'],
   320, 14000, ARRAY['he'], false),
  ('תיעוד אירוע ביטחוני בצפון (תרגיל)',
   'נרטיב עבר ששימש לתרגול משתמשים',
   true, ARRAY['israel','arab'], now() - interval '90 days',
   ARRAY['item-6001','item-6002'], ARRAY['telegram'],
   2100, 56000, ARRAY['he','ar'], false),
  ('פוסטים מבוטים על חטופים',
   'חשבונות מזויפים מפיצים מידע כוזב למשפחות',
   true, ARRAY['israel','intl'], now() - interval '6 hours',
   ARRAY['item-7001','item-7002','item-7003'], ARRAY['x','facebook'],
   950, 38000, ARRAY['he','en'], true)
) AS v(title, summary, is_anomaly, arena, detected_at,
       item_list, platforms, shares_count, views_count, languages, is_flagged)
WHERE NOT EXISTS (SELECT 1 FROM narrative n WHERE n.title = v.title);

------------------------------------------------------------------------------
-- simulated_narrative, event, action, event_log (ids generated by the DB)
------------------------------------------------------------------------------
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM event) THEN
    RAISE NOTICE 'event table is not empty, skipping event/action/log seed';
    RETURN;
  END IF;

  -- simulation 1: two narratives share one generated simulation_id
  INSERT INTO simulated_narrative (narrative_id, simulation_id)
  SELECT n.narrative_id, s.simulation_id
  FROM narrative n
  CROSS JOIN (SELECT gen_random_uuid() AS simulation_id) s
  WHERE n.title IN ('תיעוד אירוע ביטחוני בצפון (תרגיל)', 'תמונות מזויפות מהגבול הצפוני');

  -- simulation 2
  INSERT INTO simulated_narrative (narrative_id, simulation_id)
  SELECT n.narrative_id, gen_random_uuid()
  FROM narrative n
  WHERE n.title = 'תיעוד אירוע ביטחוני בצפון (תרגיל)';

  -- event (one open real event per narrative; simulations may repeat)
  INSERT INTO event (narrative_id, severity, status, is_simulation, created_by, created_at)
  VALUES
    ((SELECT narrative_id FROM narrative WHERE title = 'תמונות מזויפות מהגבול הצפוני'),
     'high', 'in_progress', false, 'user-alice', now() - interval '3 days'),
    ((SELECT narrative_id FROM narrative WHERE title = 'קמפיין בערבית נגד הסכמי נורמליזציה'),
     'critical', 'open', false, 'user-alice', now() - interval '30 hours'),
    ((SELECT narrative_id FROM narrative WHERE title = 'סרטון מניפולטיבי על פעילות צה"ל בעזה'),
     'high', 'in_progress', false, 'user-carol', now() - interval '20 hours'),
    ((SELECT narrative_id FROM narrative WHERE title = 'תיעוד אירוע ביטחוני בצפון (תרגיל)'),
     'medium', 'in_progress', true, 'system', now() - interval '5 hours');

  INSERT INTO event (narrative_id, severity, status, is_simulation, created_by, created_at,
                     closed_at, closed_by, closure_summary)
  VALUES
    ((SELECT narrative_id FROM narrative WHERE title = 'שמועה על מחסור בדלק'),
     'medium', 'closed', false, 'user-bob', now() - interval '2 days',
     now() - interval '1 day', 'user-bob',
     'השמועה הופרכה והופצה הודעת דו"צ. אין התפתחויות נוספות.'),
    ((SELECT narrative_id FROM narrative WHERE title = 'תיעוד אירוע ביטחוני בצפון (תרגיל)'),
     'low', 'closed', true, 'system', now() - interval '10 days',
     now() - interval '9 days', 'user-bob', 'תרגיל הושלם בהצלחה.');

  -- action (event found through its narrative)
  INSERT INTO action (event_id, action_type, title, description, performed_by, performed_at)
  VALUES
    ((SELECT e.event_id FROM event e
        WHERE e.is_simulation = false
          AND e.narrative_id = (SELECT narrative_id FROM narrative WHERE title = 'תמונות מזויפות מהגבול הצפוני')),
     'source_analysis', 'ניתוח מקור התמונות', 'התמונות מקורן בארכיון 2019',
     'user-alice', now() - interval '70 hours'),
    ((SELECT e.event_id FROM event e
        WHERE e.is_simulation = false
          AND e.narrative_id = (SELECT narrative_id FROM narrative WHERE title = 'תמונות מזויפות מהגבול הצפוני')),
     'consultation', 'התייעצות עם קצין המבצעים', NULL,
     'user-alice', now() - interval '60 hours'),
    ((SELECT e.event_id FROM event e
        WHERE e.is_simulation = false
          AND e.narrative_id = (SELECT narrative_id FROM narrative WHERE title = 'שמועה על מחסור בדלק')),
     'fact_check', 'בדיקה מול משרד האנרגיה', 'אין מחסור בפועל',
     'user-bob', now() - interval '40 hours'),
    ((SELECT e.event_id FROM event e
        WHERE e.is_simulation = false
          AND e.narrative_id = (SELECT narrative_id FROM narrative WHERE title = 'שמועה על מחסור בדלק')),
     'official_response', 'פרסום הודעת דו"צ מפריכה', NULL,
     'user-bob', now() - interval '30 hours'),
    ((SELECT e.event_id FROM event e
        WHERE e.is_simulation = false
          AND e.narrative_id = (SELECT narrative_id FROM narrative WHERE title = 'סרטון מניפולטיבי על פעילות צה"ל בעזה')),
     'reporter_contact', 'תיאום עם כתב בינלאומי', 'נשלח חומר הפרכה',
     'user-carol', now() - interval '10 hours');

  -- soft-deleted action
  INSERT INTO action (event_id, action_type, title, description, performed_by, performed_at,
                      deleted_at, deleted_by)
  VALUES
    ((SELECT e.event_id FROM event e
        WHERE e.is_simulation = false
          AND e.narrative_id = (SELECT narrative_id FROM narrative WHERE title = 'תמונות מזויפות מהגבול הצפוני')),
     'other', 'רישום שגוי', 'נמחק בטעות', 'user-alice',
     now() - interval '55 hours', now() - interval '54 hours', 'user-alice');

  -- event_log (append-only). Each row finds its event by narrative title, simulation flag and
  -- final status, and its action (optional) by title.
  INSERT INTO event_log (event_id, action_id, kind, actor_id, from_value, to_value, details, client, at)
  SELECT e.event_id, a.action_id, v.kind, v.actor_id, v.from_value, v.to_value,
         v.details::jsonb, v.client, v.at
  FROM (VALUES
    ('תמונות מזויפות מהגבול הצפוני', false, 'in_progress', NULL,                       'event_created',        'user-alice', NULL,          'open',        '{}',                                         'web',    now() - interval '3 days'),
    ('תמונות מזויפות מהגבול הצפוני', false, 'in_progress', 'ניתוח מקור התמונות',        'action_created',       'user-alice', NULL,          NULL,          '{"title":"ניתוח מקור התמונות"}',             'web',    now() - interval '70 hours'),
    ('תמונות מזויפות מהגבול הצפוני', false, 'in_progress', NULL,                       'event_status_changed', 'system',     'open',        'in_progress', '{}',                                         'system', now() - interval '70 hours'),
    ('תמונות מזויפות מהגבול הצפוני', false, 'in_progress', 'התייעצות עם קצין המבצעים',  'action_created',       'user-alice', NULL,          NULL,          '{"title":"התייעצות עם קצין המבצעים"}',       'mobile', now() - interval '60 hours'),
    ('תמונות מזויפות מהגבול הצפוני', false, 'in_progress', 'רישום שגוי',                'action_created',       'user-alice', NULL,          NULL,          '{"title":"רישום שגוי"}',                     'web',    now() - interval '55 hours'),
    ('תמונות מזויפות מהגבול הצפוני', false, 'in_progress', 'רישום שגוי',                'action_deleted',       'user-alice', NULL,          NULL,          '{}',                                         'web',    now() - interval '54 hours'),
    ('שמועה על מחסור בדלק',          false, 'closed',      NULL,                       'event_created',        'user-bob',   NULL,          'open',        '{}',                                         'web',    now() - interval '2 days'),
    ('שמועה על מחסור בדלק',          false, 'closed',      'בדיקה מול משרד האנרגיה',   'action_created',       'user-bob',   NULL,          NULL,          '{"title":"בדיקה מול משרד האנרגיה"}',         'web',    now() - interval '40 hours'),
    ('שמועה על מחסור בדלק',          false, 'closed',      'פרסום הודעת דו"צ מפריכה',  'action_created',       'user-bob',   NULL,          NULL,          '{"title":"פרסום הודעת דו\"צ מפריכה"}',       'web',    now() - interval '30 hours'),
    ('שמועה על מחסור בדלק',          false, 'closed',      NULL,                       'event_closed',         'user-bob',   'in_progress', 'closed',      '{}',                                         'web',    now() - interval '1 day'),
    ('קמפיין בערבית נגד הסכמי נורמליזציה', false, 'open',  NULL,                       'event_created',        'user-alice', NULL,          'open',        '{}',                                         'mobile', now() - interval '30 hours'),
    ('סרטון מניפולטיבי על פעילות צה"ל בעזה', false, 'in_progress', NULL,               'event_created',        'user-carol', NULL,          'open',        '{}',                                         'web',    now() - interval '20 hours'),
    ('סרטון מניפולטיבי על פעילות צה"ל בעזה', false, 'in_progress', 'תיאום עם כתב בינלאומי', 'action_created',   'user-carol', NULL,          NULL,          '{"title":"תיאום עם כתב בינלאומי"}',          'web',    now() - interval '10 hours'),
    ('תיעוד אירוע ביטחוני בצפון (תרגיל)', true, 'in_progress', NULL,                   'event_created',        'system',     NULL,          'open',        '{"simulation":true}',                        'system', now() - interval '5 hours'),
    ('תיעוד אירוע ביטחוני בצפון (תרגיל)', true, 'closed',  NULL,                       'event_created',        'system',     NULL,          'open',        '{"simulation":true}',                        'system', now() - interval '10 days'),
    ('תיעוד אירוע ביטחוני בצפון (תרגיל)', true, 'closed',  NULL,                       'event_closed',         'user-bob',   'open',        'closed',      '{}',                                         'web',    now() - interval '9 days')
  ) AS v(narrative_title, is_simulation, event_status, action_title, kind, actor_id,
         from_value, to_value, details, client, at)
  JOIN narrative n ON n.title = v.narrative_title
  JOIN event e     ON e.narrative_id = n.narrative_id
                  AND e.is_simulation = v.is_simulation
                  AND e.status = v.event_status
  LEFT JOIN action a ON a.event_id = e.event_id AND a.title = v.action_title;
END $$;

COMMIT;
